best = {k: max(range(3), key=lambda i: v[i]) for k, v in table.items()}
assert best == {'muscle': 0, 'liver': 2, 'skin': 1}
for k, v in table.items():
    assert sorted(v)[-1] >= 85 and sorted(v)[-2] <= 4
